pub fn add_usize(a: usize, b: usize) -> usize { a + b }
pub fn add_isize(a: isize, b: isize) -> isize { a + b }
pub fn div_u32(a: u32, b: u32) -> u32 { a / b }
pub fn not_u8(a: u8) -> u8 { !a }
pub fn shl_u8(a: u8, n: u32) -> u8 { a << n }
